package com.example.zerohaus.Util

/**
 * Textos de la app en el idioma indicado (nombre tal como aparece en Ajustes). Por defecto, español.
 */
fun getCadenas(idioma: String): AppCadenas = when (idioma) {
    "English"    -> english
    "Català"     -> catala
    "Euskara"    -> euskara
    "Galego"     -> galego
    "Português"  -> portugues
    "Français"   -> francais
    "Deutsch"    -> deutsch
    "Italiano"   -> italiano
    "العربية"    -> arabe
    "中文"        -> chino
    "Română"     -> rumano
    "Nederlands" -> neerlandes
    "Polski"     -> polaco
    else         -> espanol
}

/**
 * Código ISO 639-1 del idioma (nombre tal como aparece en Ajustes): lo usan
 * Firebase Auth para sus emails y el formato de los números. Por defecto, "es".
 */
fun codigoIdioma(idioma: String): String = when (idioma) {
    "English"    -> "en"
    "Català"     -> "ca"
    "Euskara"    -> "eu"
    "Galego"     -> "gl"
    "Português"  -> "pt"
    "Français"   -> "fr"
    "Deutsch"    -> "de"
    "Italiano"   -> "it"
    "العربية"    -> "ar"
    "中文"        -> "zh"
    "Română"     -> "ro"
    "Nederlands" -> "nl"
    "Polski"     -> "pl"
    else         -> "es"
}

